/* Complete studio photograph generated by OpenAI from actual product references. */
window.BasketLotImage={
  async load(url){const image=new Image();image.src=url;await image.decode();return image},
  async referenceBoards(items){
    // Pair identity photographs only to respect the API's 16-reference limit.
    // This contact sheet is never used as the final storefront photograph.
    const boards=[];
    for(let i=0;i<items.length;i+=2){
      const c=document.createElement('canvas');c.width=1024;c.height=1536;const ctx=c.getContext('2d');
      ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);
      for(let j=0;j<2&&items[i+j];j++){
        const image=await this.load(items[i+j].data_url),scale=Math.min(960/image.naturalWidth,680/image.naturalHeight);
        const w=image.naturalWidth*scale,h=image.naturalHeight*scale;
        ctx.drawImage(image,(1024-w)/2,j*768+32+(680-h)/2,w,h);
        ctx.font='24px Arial';ctx.fillStyle='#222';ctx.textAlign='center';ctx.fillText('Reference '+(i+j+1),512,j*768+746);
      }
      const blob=await new Promise(resolve=>c.toBlob(resolve,'image/webp',.92));
      if(!blob||blob.type!=='image/webp'||blob.size>560000)throw new Error('invalid_reference_board');
      boards.push(await this.base64(blob));
    }
    return boards;
  },
  async render(assets,size=1024){
    const c=document.createElement('canvas');c.width=c.height=size;
    // OpenAI generates the COMPLETE photograph, including products and badges.
    // Never paste catalog thumbnails or fabricate shadows over the scene.
    c.getContext('2d').drawImage(await this.load(assets.scene),0,0,size,size);
    return c;
  },
  async compress(canvas,maxBytes=150000){
    for(const width of [1024,768]){
      const c=document.createElement('canvas');c.width=c.height=width;c.getContext('2d').drawImage(canvas,0,0,width,width);
      for(const quality of [.86,.80,.74,.68]){
        const blob=await new Promise(resolve=>c.toBlob(resolve,'image/webp',quality));
        if(!blob||blob.type!=='image/webp')throw new Error('Este navegador não permite exportar WebP.');
        if(blob.size<=maxBytes)return {blob,width};
      }
    }
    throw new Error('Não foi possível compactar a foto com qualidade.');
  },
  async base64(blob){return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)})},
  error(e){
    const value=String(e?.message||e),messages={hygiene_lot_required:'Selecione o lote de limpeza e higiene.',product_image_unavailable:'Uma foto não pôde ser carregada. Confira as fotos dos produtos.',composition_changed:'A composição ou as fotos mudaram. Gere uma nova prévia.',openai_key_missing:'O serviço de imagem ainda não está configurado.',generation_attempt_limit:'Limite de três tentativas atingido. Confira o erro antes de continuar.',generation_interrupted:'A geração foi interrompida. Você pode tentar novamente.',lot_not_mounted:'Confirme a montagem antes de gerar a imagem.',invalid_unit_quantity:'As etiquetas exigem quantidade inteira por produto.'};
    return messages[value]||(value.startsWith('product_image_missing')?'Há produto sem foto. Cadastre a foto antes de gerar.':value.startsWith('openai_http')?'O provedor não conseguiu gerar a fotografia. Tente novamente mais tarde.':'Não foi possível concluir a imagem. '+value);
  },
  async open(lotId,api,esc){
    const $=s=>document.querySelector(s),session=Symbol();this.session=session;
    const active=()=>this.session===session&&$('#editor').open;
    $('#editor').addEventListener('close',()=>{if(this.session===session&&!$('#editor').open)this.session=null},{once:true});
    const close=()=>{$('#editor').close();this.session=null};
    $('#editorTitle').textContent='Imagem do lote';$('#editorBody').innerHTML='<p>Carregando composição…</p>';
    $('#editorActions').innerHTML='<button class="secondary" id="lotImageClose" type="button">Fechar</button>';$('#lotImageClose').onclick=close;
    if(!$('#editor').open)$('#editor').showModal();
    let context;try{context=await api('context',{lot_id:lotId})}catch(e){if(active())$('#editorBody').textContent=this.error(e);return}
    if(!active())return;
    $('#editorBody').innerHTML='<p>Uma foto de cada produto, com quantidade por cesta na etiqueta. Confira as embalagens antes de usar no site.</p>'+
      (context.needs_hygiene?'<label>Incluir limpeza e higiene<select id="lotImageHygiene">'+(context.hygiene_lots||[]).map(h=>'<option value="'+esc(h.id)+'">'+esc(h.short_code)+(h.sale_enabled?' · ativo no site':' · fora do site')+'</option>').join('')+'</select></label>':'')+
      '<div id="lotImageProgress" class="sub" role="status" aria-live="polite"></div><div id="lotImagePreview"></div><p class="sub">Fotografia OpenAI em qualidade alta · WebP quadrado, até 150 KB. Gerar a imagem não altera estoque nem ativa a venda.</p>';
    $('#editorActions').innerHTML='<button class="secondary" id="lotImageClose" type="button">Fechar</button><button class="primary" id="lotImageStart" type="button">Gerar prévia</button><button class="secondary" id="lotImageRegenerate" type="button" hidden>Gerar outra versão</button><button class="primary" id="lotImagePublish" type="button" hidden>Usar imagem no site</button>';
    $('#lotImageClose').onclick=close;
    let regenerateRequested=false;const regenerate=document.querySelector('#lotImageRegenerate');
    const progress=$('#lotImageProgress'),start=$('#lotImageStart'),publish=$('#lotImagePublish');
    const show=job=>{
      if(!active())return;
      $('#lotImagePreview').innerHTML=job.image_url?'<img src="'+esc(job.image_url)+'" alt="Prévia da composição do lote" style="display:block;width:100%;max-width:520px;aspect-ratio:1;object-fit:contain;margin:12px auto;border-radius:12px"><ul>'+job.manifest.map(x=>'<li>'+esc(x.quantity)+' un. · '+esc(x.name)+'</li>').join('')+'</ul>':'';
      progress.textContent=job.status==='published'?'Imagem aprovada. O site a usará quando oferecer esta composição.':job.status==='preview'?'Prévia pronta · '+(Number(job.byte_size)/1000).toFixed(1)+' KB · '+job.width+' × '+job.width+' px. Confira os produtos e as etiquetas.':'';
      regenerate.hidden=!['preview','published'].includes(job.status);regenerate.onclick=()=>{regenerateRequested=true;start.onclick()};publish.hidden=job.status!=='preview';start.hidden=false;start.textContent=['preview','published'].includes(job.status)?'Gerar ou retomar prévia':'Gerar prévia';
      publish.onclick=async()=>{publish.disabled=true;start.disabled=true;regenerate.disabled=true;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=true;try{const data=await api('publish',{job_id:job.id});show(data.job)}catch(e){if(active())progress.textContent=this.error(e)}finally{if(active()){publish.disabled=false;start.disabled=false;regenerate.disabled=false;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=false}}};
    };
    const process=async job=>{
      start.disabled=true;regenerate.disabled=true;regenerate.hidden=true;publish.hidden=true;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=true;
      try{
        const deadline=Date.now()+260000;
        while(job.status==='generating'){
          if(!active())return;progress.textContent='Fotografando a composição com a OpenAI. Você pode fechar e retomar a prévia depois.';
          if(Date.now()>deadline)throw new Error('generation_interrupted');
          await new Promise(resolve=>setTimeout(resolve,3000));if(!active())return;
          job=(await api('status',{job_id:job.id})).job;
        }
        if(!active())return;if(job.status==='failed')throw new Error(job.error);
        if(job.status==='scene_ready'){
          progress.textContent='Compactando a fotografia completa…';
          const assets=await api('assets',{job_id:job.id});if(!active())return;
          const canvas=await this.render(assets),result=await this.compress(canvas);if(!active())return;
          job=(await api('save_preview',{job_id:job.id,width:result.width,image_base64:await this.base64(result.blob)})).job;
        }
        show(job);
      }catch(e){if(active())progress.textContent=this.error(e)}finally{if(active()){start.disabled=false;regenerate.disabled=false;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=false}}
    };
    start.onclick=async()=>{const requestAnother=regenerateRequested;regenerateRequested=false;regenerate.hidden=true;publish.hidden=true;start.disabled=true;regenerate.disabled=true;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=true;progress.textContent='Preparando composição…';try{const refs=await api('references',{lot_id:lotId,hygiene_lot_id:document.querySelector('#lotImageHygiene')?.value||null});if(!active())return;const boards=refs.paired?await this.referenceBoards(refs.items):[];if(!active())return;const data=await api('start',{regenerate:requestAnother,reference_boards:boards,composition_key:refs.composition_key,lot_id:lotId,hygiene_lot_id:$('#lotImageHygiene')?.value||null});if(active())await process(data.job)}catch(e){if(active())progress.textContent=this.error(e)}finally{if(active()){start.disabled=false;regenerate.disabled=false;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=false}}};
    const restore=async()=>{
      const selected=$('#lotImageHygiene')?.value||null,previous=(context.jobs||[]).find(j=>(j.hygiene_lot_id||null)===selected);
      start.hidden=false;regenerate.hidden=true;publish.hidden=true;$('#lotImagePreview').innerHTML='';progress.textContent='';
      if(previous){start.disabled=true;regenerate.disabled=true;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=true;try{const d=await api('status',{job_id:previous.id});if(active())await process(d.job)}catch(e){if(active())progress.textContent=this.error(e)}finally{if(active()){start.disabled=false;regenerate.disabled=false;if($('#lotImageHygiene'))$('#lotImageHygiene').disabled=false}}}
    };
    if(context.needs_hygiene&&!(context.hygiene_lots||[]).length){start.disabled=true;regenerate.disabled=true;progress.textContent='Monte um lote de limpeza e higiene antes de gerar a imagem completa.'}
    else{if($('#lotImageHygiene'))$('#lotImageHygiene').onchange=restore;await restore()}
  }
};

/* Progressive bootstrap for isolated Marketing modules. */
(()=>{
  if(!document.querySelector('link[data-da-marketing-template-center]')){
    const link=document.createElement('link');
    link.rel='stylesheet';
    link.href='/vitrine/admin/marketing/template-center.css?v=meta-template-center-v1';
    link.dataset.daMarketingTemplateCenter='1';
    document.head.appendChild(link);
  }
  import('/vitrine/admin/marketing/template-center.js?v=meta-template-center-v1').catch(error=>console.warn('marketing-template-center-load',String(error?.message||error).slice(0,160)));
  import('/vitrine/admin/marketing/campaign-entry.js?v=marketing-campaign-v1').catch(error=>console.warn('marketing-campaign-entry-load',String(error?.message||error).slice(0,160)));
})();
